func valueAIUsageRecord(p unsafe.Pointer, c int32) any {
	r := (*aiusage.AIUsageRecord)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		if r.ProviderID == "" {
			return nil
		}
		return string(r.ProviderID)
	case 4:
		return string(r.ProviderKind)
	case 5:
		return r.Model
	case 6:
		return string(r.Task)
	case 7:
		return string(r.Surface)
	case 8:
		if r.UserID == "" {
			return nil
		}
		return string(r.UserID)
	case 9:
		if r.AgentDefinitionID == "" {
			return nil
		}
		return string(r.AgentDefinitionID)
	case 10:
		if r.ThreadID == "" {
			return nil
		}
		return string(r.ThreadID)
	case 11:
		if r.RunID == "" {
			return nil
		}
		return string(r.RunID)
	case 12:
		if r.Feature == "" {
			return nil
		}
		return string(r.Feature)
	case 13:
		if r.SubjectType == "" {
			return nil
		}
		return string(r.SubjectType)
	case 14:
		if r.SubjectID == "" {
			return nil
		}
		return r.SubjectID
	case 15:
		return r.Succeeded
	case 16:
		if r.ErrorClass == "" {
			return nil
		}
		return r.ErrorClass
	case 17:
		if r.ErrorMessage == "" {
			return nil
		}
		return r.ErrorMessage
	case 18:
		return r.Streamed
	case 19:
		return r.LatencyMs
	case 20:
		return int64(r.InputTokens)
	case 21:
		return int64(r.OutputTokens)
	case 22:
		return int64(r.ReasoningTokens)
	case 23:
		if r.CostUSD == nil {
			return nil
		}
		return *r.CostUSD
	case 24:
		if r.TraceID == "" {
			return nil
		}
		return r.TraceID
	case 25:
		if r.SpanID == "" {
			return nil
		}
		return r.SpanID
	case 26:
		if r.OwnerKind == "" {
			return nil
		}
		return string(r.OwnerKind)
	case 27:
		if r.OwnerID == "" {
			return nil
		}
		return string(r.OwnerID)
	case 28:
		if r.DelegateCallID == "" {
			return nil
		}
		return r.DelegateCallID
	case 29:
		if r.AgentDefinitionVersion == nil {
			return nil
		}
		return *r.AgentDefinitionVersion
	case 30:
		if r.Attempt == 0 {
			return nil
		}
		return int64(r.Attempt)
	case 31:
		return r.Failover
	case 32:
		return int64(r.CacheReadTokens)
	case 33:
		return int64(r.CacheWriteTokens)
	case 34:
		if r.FirstTokenMs == nil {
			return nil
		}
		return *r.FirstTokenMs
	case 35:
		if r.RecordedAtMs == nil {
			return nil
		}
		return *r.RecordedAtMs
	case 36:
		if r.AdvisorModel == "" {
			return nil
		}
		return r.AdvisorModel
	case 37:
		return int64(r.AdvisorCalls)
	case 38:
		return int64(r.AdvisorInputTokens)
	case 39:
		return int64(r.AdvisorOutputTokens)
	case 40:
		return int64(r.AdvisorCacheReadTokens)
	case 41:
		return int64(r.AdvisorCacheWriteTokens)
	case 42:
		if r.AdvisorCostUSD == nil {
			return nil
		}
		return *r.AdvisorCostUSD
	case 43:
		return r.CreatedAt
	case 44:
		return r.Batched
	}
	return nil
}

